  const openDay=sortedDays.find(d=>d.poll==='open');
  async function refresh(){try{const r=await fetch('/api/club',{cache:'no-store'});const j=await r.json() as PublicClub & {error?:string};if(!r.ok)throw new Error(j.error);setData(j);setError('');return j as PublicClub;}catch(e){setError(e instanceof Error?e.message:'Unable to load club.');return null;}finally{setLoading(false)}}
  useEffect(()=>{const q=new URLSearchParams(location.search),h=new URLSearchParams(location.hash.slice(1));const v=q.get('view');if(NAV.some(x=>x[0]===v))setView(v as View);if(q.get('day'))setDayId(q.get('day')!);if(TEAMS.includes(q.get('team') as Team))setTeamFilter(q.get('team')!);if(h.get('invite')||q.get('invite')){location.replace('/join?invite='+encodeURIComponent(h.get('invite')||q.get('invite')!));return;}if(q.get('invite_error'))toast.error('This link has been used or is unavailable. Sign in if you already joined, or ask the organiser for your current invite.');if(h.get('setup')){setSetupKey(h.get('setup')!);setModal('setup')}void refresh();},[]);
  function navigate(v:View,id?:string){setView(v);if(id)setDayId(id);const q=new URLSearchParams();if(v!=='overview')q.set('view',v);if(id)q.set('day',id);history.replaceState(null,'',location.pathname+(q.size?'?'+q:'')+location.hash);window.scrollTo({top:0,behavior:'smooth'})}
