  function Leaders({kind='goals'}:{kind?:'goals'|'assists'|'wins'}){const ranked=[...players].sort((a,b)=>b[kind]-a[kind]).filter(p=>p[kind]>0).slice(0,5);return ranked.length?<div>{ranked.map((p,i)=><button className="leader-row w-full text-left" key={p.id} onClick={()=>setSelectedPlayer(p)}><span className="tiny-label w-4">{i+1}</span><Avatar p={p}/><div className="grow"><strong>{p.name}</strong><small>{TEAM[p.team].name} · {p.position}</small></div><span className="leader-value">{p[kind]}</span></button>)}</div>:<NoData title="No stats yet">The leaderboard fills in as match results are added.</NoData>}
